    public void new()
    {
        pages = new Map(Types::String, Types::Class);
	}

public TFMPage getPage(str _id)
{
    return pages.exists(_id) ? pages.lookup(_id) : null;
}

public Set getPagesUsingProcess(TFMProcessID _processId)
{
    MapEnumerator   mEnum = pages.getEnumerator();
    Set             pagesUsingProcess = new Set(Types::Class);

    while (mEnum.moveNext())
    {
        TFMPage page = mEnum.currentValue();

        if (classIdGet(page) == classNum(TFMPageUnplannedItemRegistration))
        {
            TFMPageUnplannedItemRegistration uirPage = page as TFMPageUnplannedItemRegistration;

            if (uirPage.getConfiguration().parmType() == _processId)
            {
                pagesUsingProcess.add(uirPage);
            }
        }
        if (classIdGet(page) == classNum(TFMPageLookup))
        {
            TFMPageLookup lookupPage = page as TFMPageLookup;

            if (lookupPage.getConfiguration().parmType() == _processId)
            {
                pagesUsingProcess.add(lookupPage);
            }
        }
    }
        return pagesUsingProcess;
}

	public void setDocumentHandler(TFMDocumentHandler _docHand)
    {
        MapEnumerator	mEnum = pages.getEnumerator();
        TFMPage			page;
		while (mEnum.moveNext())
        {
            page = mEnum.currentValue();
            page.setDocumentHandler(_docHand);
        }
    }
